function usePermission() {
	const user = useAuthStore((s) => s.user);
	const isGuest = user?.username === "guest";
	const isAdmin = user?.role === "admin" && !isGuest;
	const isOperator = user?.role === "operator" && !isGuest;
	const isDemoAdmin = isGuest && (user?.role === "admin" || user?.role === "operator");
	const canRestartDirectly = user?.role === "admin";
	const can = (action) => {
		switch (action) {
			case "add-server":
			case "configure-llm":
			case "manage-users": return isAdmin;
			case "approve-action": return isAdmin || isOperator || isDemoAdmin;
			case "view-audit":
			case "view-plugins":
			case "view-settings": return isAdmin || isOperator || isDemoAdmin;
			default: return false;
		}
	};
	return {
		isAdmin,
		isOperator,
		isGuest,
		isDemoAdmin,
		canRestartDirectly,
		can
	};
}
