var useInsightsStore = create((set) => ({
	insightsByNode: {},
	loadingByNode: {},
	fetchInsights: async (nodeId) => {
		if (!nodeId || nodeId === "all") return;
		set((state) => ({ loadingByNode: {
			...state.loadingByNode,
			[nodeId]: true
		} }));
		try {
			const data = await api(`/api/nodes/${nodeId}/insights`);
			if (data && data.insights) set((state) => ({ insightsByNode: {
				...state.insightsByNode,
				[nodeId]: data.insights
			} }));
		} catch (err) {
			console.error(`Failed to fetch insights for node ${nodeId}:`, err);
		} finally {
			set((state) => ({ loadingByNode: {
				...state.loadingByNode,
				[nodeId]: false
			} }));
		}
	},
	invalidate: (nodeId) => {
		set((state) => {
			const copy = { ...state.insightsByNode };
			delete copy[nodeId];
			return { insightsByNode: copy };
		});
	}
}));
