//#region src/utils/formatActor.ts
/**
* Maps a demo user ID or raw UUID to a friendly display name.
* In demo mode, "demo-user" maps to "guest".
* Other UUIDs are truncated to first 8 chars.
*/
function formatActorName(userId) {
	if (!userId) return t("common.system");
	if (userId === "demo-user") return "guest";
	if (userId.includes("-") && userId.length > 12) return userId.substring(0, 8) + "…";
	return userId;
}
