			const res = await api(`/api/nodes/${id}/containers/${containerId}/restart`, { method: "POST" });
			if (res?.error) useToastStore.getState().addToast("error", t("chat.toast.failure"), t("node_detail.toast.container_restart_failed", {
				name,
				error: res.error
			}));
			else {
				useToastStore.getState().addToast("success", t("chat.toast.success"), t("node_detail.toast.container_restarted", { name }));
				await fetchContainersList();
			}
